  str_cn9_item_7000710 = "ภาชนะเก็บของสักการะจากเครื่องลายครามสีฟ้าขาว",
  str_cn9_item_7000711 = "ที่วางเทียนหอมสิงห์เคลือบขาว",
  str_cn9_item_7000712 = "สแตนด์เทียนเคลือบขาว",
  str_cn9_item_7000713 = "ถ้วยแปดเหลี่ยมเคลือบขาว",
  str_cn9_item_intro_7000700 = "จานกระเบื้องที่มีเคลือบสีขาวบริสุทธิ์\nลวดลายละเอียดที่เหมือนกับเศษน้ำแข็งที่แตกกระจัดกระจายอยู่บนผิวของมัน",
  str_cn9_item_intro_7000701 = "ถ้วยพอร์ซเลนที่มีเคลือบขาว\nขอบรูปไข่ออกแบบอย่างละเอียดที่แผ่ออกไป และฐานมีรูปแบบเหมือนกิ่งไม้ที่แตกสาขา ลำตัวถ้วยแสดงลายปักพลุมที่มีความละเอียดสามมิติที่น่าสนใจ",
  str_cn9_item_intro_7000702 = "จานกระเบื้องที่มีเคลือบสีขาวบริสุทธิ์\nลายดอกไม้สีน้ำเงินและขาวที่มีความสง่างามเรียบร้อยตั้งแต่ขอบจาน",
  str_cn9_item_intro_7000703 = "เครื่องบูชาเซรามิกที่มีเคลือบสีเซลาดอนเขียวอุดมคติ มีรูขนาดกว้างและแข็งแรง คอสั้นโค้งงามเข้าด้านใน และลำตัวเครื่องบูชาที่อวบอิ่ม สามขาที่ประดับด้วยหัวสัตว์ป่าอย่างงดงาม แสดงให้เห็นถึงฝีมือศิลปะที่ยอดเยี่ยม\n\nหมายเหตุ:\nเครื่องบูชา - มักใช้สำหรับเผาธูป",
  str_cn9_item_intro_7000704 = "เครื่องลายครามที่มีการเคลือบด้วยเคลือบสีขาว มันมีเคลือบที่ส่องแสงและมีรอยแตกเล็กๆ ลายละเอียดประดับคอและลำตัวของมัน ในขณะที่มือจับที่ถูกประดิษฐ์อย่างฉลาดเหมือนงวงช้าง เพิ่มความสง่างามแบบรีกัล\n\nหมายเหตุ:\nเครื่องลายคราม - โดยปกติใช้สำหรับเสิร์ฟเครื่องดื่มหรือนำมาแสดง\nรอยแตกเป็นปรากฏการณ์ธรรมชาติของเคลือบเครื่องลายคราม",
  str_cn9_item_intro_7000705 = "ช้อนซุปเครื่องลายครามที่มีเคลือบสีขาวบริสุทธิ์\nท้ายของช้อนมีรูปร่างเชิงเส้นที่งดงาม และลำตัวของมันได้รับการประดับด้วยลายดอกไม้ที่ซับซ้อน",
  str_cn9_item_intro_7000706 = "หม้อเครื่องลายครามที่มีฝาครอบด้วยเคลือบซีลาดอนวาววิ้ง\nเคลือบที่ด้านบนมีรอยแตกงามตา ในขณะที่ฐานไม่มีเคลือบและเปิดเผยส่วนที่เป็นสีแดง สร้างความแตกต่างที่น่าสนใจ ตกแต่งด้วยหูรูปต่างหูสองข้าง ทำให้ดูสวยงามยิ่งขึ้น",
  str_cn9_item_intro_7000707 = "แจกันเครื่องลายครามที่มีเคลือบสีแอเชอร์\nผิวเคลือบแสดงลวดลายรอยแตกละเอียดที่ซับซ้อน และปากแจกัน มือจับ และส่วนตกแต่งยังคงสมบูรณ์อย่างสมบูรณ์แบบ ทำให้แจกันนี้เป็นพยานของทั้งศิลปะและฝีมือช่าง\n\nหมายเหตุ:\nรอยแตกเป็นปรากฏการณ์ธรรมชาติของเคลือบเครื่องลายคราม",
  str_cn9_item_intro_7000708 = "กระบวนทองเจือจางในรูปร่างสัตว์\nมีหูกระต่าย เนื้อที่แรงบันดาลใจมาจากระยือ และเท้าที่มีรูปร่างเช่นเดียวกับเกือกม้า ดวงตาที่ตั้งแต่งด้วยหินสีฟ้าอัญชันและรูปปากกลมเพิ่มความน่าสนใจ ในขณะที่มีลวดลายเส้นเชื่อมเป็นเมฆประดับตัว ทำให้มีลักษณะเฉพาะที่แท้จริง\n\nหมายเหตุ:\nกระบวน - ใช้เสิร์ฟเครื่องดื่มหรือนำไปแสดง\nลวดลายที่สามารถเชื่อมต่อกันเน้นที่เทคนิคการสร้างที่ไม่ธรรมดา",
  str_cn9_item_intro_7000709 = "เซนเซอร์สำหรับเผาหอมจากทองแดงที่มีลายเก๋ไก๋\nขอบของรูเปิดถูกตกแต่งด้วยลายเมฆและฟ้าผ่า, คอมีลายสัตว์, ไหล่แสดงลายเทาเทีย, และท้องแสดงลายคลื่นและลายที่อธิบายสองมังกรที่เล่นกับมุก\n\nหมายเหตุ:\nเซนเซอร์ - มักจะใช้สำหรับการเผาหอม\nลายเมฆและฟ้าผ่า - จำลองการออกแบบที่ละเอียดยิบของเมฆและฟ้าผ่า, เรียกใช้พลังของธรรมชาติ\nเทาเทีย - การออกแบบที่ได้แ inspiration จากสัตว์ในตำนานเทาเทียที่มีความหิวที่น่ากลัวและลายที่ละเอียดยิบลายคลื่น - จับต้องได้ถึงธรรมชาติที่ไหลเวียนและเต็มไปด้วยพลังของคลื่นทะเลที่กำลังซัด\nภาพของมังกรสองตัวที่กำลังเล่นกับมุกเป็นลายเส้นที่เป็นที่รับใช้แทนความโชคดีตามประเพณีเดิม.",
  str_cn9_item_intro_7000710 = "เครื่องลายครามที่ตกแต่งด้วยภาพพรรณนาของคนธรรมดาอย่างละเอียด\nคอของมันมีลวดลายเชือกหลายชั้นและตกแต่งด้วยเครื่องประดับรูปมังกร ในขณะที่บ่ามีการตกแต่งด้วยภาพจำลองห้าตัว\n\nหมายเหตุ:\nวัตถุโบราณสำหรับงานศพ - วัตถุโบราณสำหรับงานศพที่พบบ่อยในสุสานโบราณ ประกอบด้วยเมล็ดข้าวที่ถูกเผา และเชื่อว่าเป็นที่พักพิงของวิญญาณที่หลงทาง",
  str_cn9_item_intro_7000711 = "เชิงธูปเครื่องลายครามในรูปสิงโตนั่ง\nสิงโตกำลังเล่นกับลูกบอลกลมใต้เท้าหน้าซ้ายและสวมกระดิ่งเล็ก ๆ สองอันรอบคอ หัวที่เอียงขึ้นและหางงอกันอย่างงามเพิ่มความน่ารัก ฐานมีช่องสำหรับวางธูป\n\nหมายเหตุ:\nเชิงธูป - เครื่องใช้ที่สวยงามที่สร้างขึ้นเพื่อวางธูปเสียบ",
  str_cn9_item_intro_7000712 = "แก้วเทียนกระเบื้องที่โค้ดด้วยเคลือบสีขาว\nมีความโค้งมนเสริมความงาม พร้อมที่วางเทียนและธูปตรงกลาง",
  str_cn9_item_intro_7000713 = "ถ้วยเซรามิกที่มีเคลือบสีขาวบริสุทธิ์\nถ้วยมีขอบแปดเหลี่ยมที่ไม่ธรรมดา และมีพื้นผิวเคลือบที่มีลายรอยแตกละเอียด ดีไซน์ของมันรวมถึงมือจับที่หายไปในปัจจุบัน\n\nหมายเหตุ:\nรอยแตกเป็นปรากฏการณ์ธรรมชาติของเคลือบเซรามิก",
